import{_ as e,o as l,c as s,aw as o}from"./chunks/framework.DLufY-ao.js";const h=JSON.parse('{"title":"Сборщик мусора","description":"","frontmatter":{},"headers":[],"relativePath":"wiki/dev-commit/js/js/theory/garbage-collection.md","filePath":"wiki/dev-commit/js/js/theory/garbage-collection.md"}'),i={name:"wiki/dev-commit/js/js/theory/garbage-collection.md"};function n(t,a,r,p,c,d){return l(),s("div",null,[...a[0]||(a[0]=[o(`<h1 id="сборщик-мусора" tabindex="-1">Сборщик мусора <a class="header-anchor" href="#сборщик-мусора" aria-label="Permalink to &quot;Сборщик мусора&quot;">​</a></h1><ul><li><p><strong>Сборщик мусора (Garbage collection, GC)</strong> - очистка памяти от недостижимых значений в браузере. GC встроенн в интерпретатор, он наблюдает за объектами и время от времени удаляет недостижимые</p></li><li><p>Примитивы - при присвоении они копируются целиком, ссылок на них не создаётся. Если в переменной была одна строка, а её заменили на другую, то предыдущая удаляется</p></li><li><p>Объекты требуют специального «сборщика мусора», который наблюдает за ссылками, т.к. на один объект может быть много ссылок из разных переменных и, при перезаписи одной из них, объект может быть всё ещё доступен из другой</p></li><li><p>Упрощение для работы с памятью: «значение остаётся в памяти, пока на него есть хотя бы одна ссылка»</p><ul><li>Верно - в том плане, что если ссылок на значение нет, то память из-под него очищается</li><li>Неверно - в другую сторону: наличие ссылки не гарантирует, что значение останется в памяти</li></ul></li><li><p>Сборщик мусора идёт от корня по ссылкам и запоминает все найденные объекты. По окончанию - он смотрит, какие объекты в нём отсутствуют и удаляет их</p></li><li><p>Применение оптимизации интерпретаторами - деление объектов на два вида «старые» и «новые». Для каждого типа выделяется своя область памяти. Каждый объект создаётся в «новой» области и, если прожил достаточно долго, мигрирует в старую. «Новая» область обычно небольшая. Она очищается часто. «Старая» – редко</p></li><li><p><strong>Замыкания</strong> LexicalEnvironment внешней функции существует в памяти до тех пор, пока существует хоть одна внутренняя функция, ссылающаяся на него через свойство [[Scope]]</p></li><li><p><strong>Оптимизация в V8</strong> JS-движки делают оптимизации замыканий по памяти. Они анализируют использование переменных и в случае, когда переменная из замыкания абсолютно точно не используется, удаляют её</p></li><li><p>clearTimeout / setInterval Сборщик мусора не чистит функции, назначенные в таймерах, пока таймеры актуальны</p></li></ul><h3 id="очистка-памяти" tabindex="-1">Очистка памяти <a class="header-anchor" href="#очистка-памяти" aria-label="Permalink to &quot;Очистка памяти&quot;">​</a></h3><div class="language-js"><button title="Copy Code" class="copy"></button><span class="lang">js</span><pre class="shiki one-light vp-code" tabindex="0"><code><span class="line"><span style="color:#A626A4;">const</span><span style="color:#986801;"> user</span><span style="color:#0184BC;"> =</span><span style="color:#383A42;"> {</span></span>
<span class="line"><span style="color:#E45649;">    name</span><span style="color:#0184BC;">:</span><span style="color:#50A14F;"> &#39;Tony&#39;</span></span>
<span class="line"><span style="color:#383A42;">}</span></span>
<span class="line"><span style="color:#383A42;">user </span><span style="color:#0184BC;">=</span><span style="color:#986801;"> null</span><span style="color:#383A42;">;</span></span></code></pre></div><h2 id="подходы-к-сборке-мусора" tabindex="-1">Подходы к сборке мусора <a class="header-anchor" href="#подходы-к-сборке-мусора" aria-label="Permalink to &quot;Подходы к сборке мусора&quot;">​</a></h2><h3 id="_1-mark-and-sweep" tabindex="-1">1. Mark and Sweep <a class="header-anchor" href="#_1-mark-and-sweep" aria-label="Permalink to &quot;1. Mark and Sweep&quot;">​</a></h3><ul><li>Самый простой алгоритм поиска и удаления мусора. Работает только тогда, когда мусор есть, если память наполнена только живыми объектами, Mark and Sweep ничего не делает.</li><li>Основной минус Mark and Sweep в том, что он фрагментирует память. В итоге он может очистить много места, но новый крупный объект все равно не сможет разместиться в оперативной памяти.</li></ul><h3 id="_2-mark-sweep-compact" tabindex="-1">2. Mark-Sweep-Compact <a class="header-anchor" href="#_2-mark-sweep-compact" aria-label="Permalink to &quot;2. Mark-Sweep-Compact&quot;">​</a></h3><ul><li>В алгоритме Mark-Sweep-Compact добавляется как раз та самая необходимая функция дефрагментации. После очистки он смещает все оставшиеся объекты и создает единое пространство свободной памяти.</li><li>С точки зрения результата Mark-Sweep-Compact оптимален. Однако сам процесс смещения объектов довольно ресурсозатратный, к тому же Mark-Sweep-Compact нужно проходить по памяти 2-3 раза, что занимает много лишнего времени.</li></ul><h3 id="_3-semispace" tabindex="-1">3. SemiSpace <a class="header-anchor" href="#_3-semispace" aria-label="Permalink to &quot;3. SemiSpace&quot;">​</a></h3><ul><li>SemiSpace (копирующий сборщик), несколько ускоряет процесс очистки и дефрагментации. SemiSpace находит живые объекты и копирует их в заранее выделенное пространство, а все остальное удаляет.</li><li>Этот алгоритм проще и быстрее Mark-Sweep-Compact, однако требует выделения дополнительного места для копирования живых объектов. К тому же сам процесс копирования также ресурсозатратен.</li></ul><h3 id="слабая-гипотеза-о-поколениях" tabindex="-1">Слабая гипотеза о поколениях <a class="header-anchor" href="#слабая-гипотеза-о-поколениях" aria-label="Permalink to &quot;Слабая гипотеза о поколениях&quot;">​</a></h3><ul><li>Согласно теории поколений, объекты “умирают молодыми” гораздо чаще, чем “старыми”. Недавно созданный объект станет мусором с гораздо большей вероятностью. Именно поэтому сборщику мусора рационально проверять такие объекты чаще.</li></ul>`,13)])])}const u=e(i,[["render",n]]);export{h as __pageData,u as default};
